"""execute_python_code_readonly ツール。"""

from __future__ import annotations

from langchain_core.tools import tool
from pathlib import Path
import asyncio
import logging
import subprocess
import tempfile

from . import _state
from ._python_fs_guard import _python_fs_guard_preamble
from ._subprocess_env import _subprocess_env
from ._workdir import _resolve_exec_workdir, _tmp_dir_parents

logger = logging.getLogger(__name__)


@tool
async def execute_python_code_readonly(code: str) -> str:
    """Run Python code generated by the LLM on the spot and return its stdout/stderr
    (read-only version that cannot write).

    Works the same way as execute_python_code (writes the code string to a temporary file and runs
    it on the spot), but never allows any write, delete or rename anywhere. Use it only for
    calculation and verification that do not modify any file, such as computing the "correct
    value" from rules or reading existing data to double-check it. To create or edit output files,
    use execute_python_code or the dedicated scripts of the matching skill instead of this tool
    (trying to write a file with this tool fails with PermissionError).

    Unlike execute_python_code, it does not need plan approval (Plan Mode)
    (it cannot write anything, so it is safe to run without an approved plan).

    Args:
        code: The full Python code to run. To use path_memory @N tokens, expand them to real
            paths the same way as execute_python_code (path_memory.resolve()).

    Returns:
        A string with "[exit code] N" followed by stdout and stderr.
        If code is empty, execution is disabled, it timed out, or starting it failed, it returns
        an "Error: ..." string instead of raising. If the code tries to write, delete or rename,
        it fails with PermissionError and the details are included in stderr.
    """
    if not code.strip():
        return "Error: code is empty."
    if not _state._CODE_EXEC_ENABLED:
        return "Error: running Python code generated by the LLM is disabled in config.ini " "([scripts] code_execution_enabled=false)."
    workdir = _resolve_exec_workdir()

    try:
        _fs_guard = _python_fs_guard_preamble([], tmp_dir_roots=_tmp_dir_parents(workdir.parent))
        tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".py", dir=str(workdir), delete=False, encoding="utf-8")
        tmp.write(_fs_guard + code)
        tmp.close()
        tmp_path = Path(tmp.name)
    except OSError as e:
        return f"Error: could not create a temporary file: {e}"

    logger.info("execute_python_code_readonly: cwd=%s", workdir)
    try:
        try:
            proc = await asyncio.to_thread(
                subprocess.run,
                [_state._SCRIPT_PYTHON, str(tmp_path)],
                cwd=str(workdir),
                capture_output=True,
                text=True,
                timeout=_state._SCRIPT_TIMEOUT,
                encoding="utf-8",
                errors="replace",
                env=_subprocess_env(),
            )
        except subprocess.TimeoutExpired:
            return f"Error: the code timed out after {_state._SCRIPT_TIMEOUT} seconds."
        except OSError as e:
            return f"Error: could not run the code: {e}"
    finally:
        tmp_path.unlink(missing_ok=True)

    parts = [f"[exit code] {proc.returncode}"]
    if proc.stdout:
        parts.append(f"[stdout]\n{proc.stdout.rstrip()}")
    if proc.stderr:
        parts.append(f"[stderr]\n{proc.stderr.rstrip()}")
    return "\n".join(parts)
